export function useLastBatch() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: settleBatchesKey(sheet),
    queryFn: () => getJson<{ last: number | null }>(`/api/sheets/${encodeURIComponent(sheet)}/settle-batches`),
    enabled: !!sheet,
  });
